previewCss:
.darma-loader-kite-flight {
  position: relative;
  width: 44px;
  height: 52px;
  transform-origin: center bottom;
  animation: darma-loader-kite-flight-sway 1.8s ease-in-out infinite;
}
.darma-loader-kite-flight::before {
  content: "";
  position: absolute;
  top: 2px;
  left: 50%;
  width: 24px;
  height: 24px;
  margin-left: -12px;
  border-radius: 4px;
  background: var(--loader-color, #6366f1);
  transform: rotate(45deg);
}
.darma-loader-kite-flight i {
  position: absolute;
  top: 26px;
  left: 50%;
  width: 2px;
  height: 24px;
  margin-left: -1px;
  background: #c7d2fe;
}
.darma-loader-kite-flight i::before {
  content: "";
  position: absolute;
  top: 6px;
  left: -4px;
  width: 10px;
  height: 5px;
  border-radius: 50%;
  background: #4338ca;
}
.darma-loader-kite-flight i::after {
  content: "";
  position: absolute;
  top: 15px;
  left: -4px;
  width: 10px;
  height: 5px;
  border-radius: 50%;
  background: #4338ca;
}
@keyframes darma-loader-kite-flight-sway {
  0%, 100% { transform: rotate(-8deg) translateY(0); }
  50% { transform: rotate(8deg) translateY(-4px); }
}

